// ── CH5 · FROZEN LAKE — storm, teamwork, crystal shard ──

svg += `<defs>
  <linearGradient id="lg-ch5" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN?'#030010':sc.sky1}"/>
    <stop offset="100%" stop-color="${isN?'#0A1020':sc.sky2}"/>
  </linearGradient>
  <radialGradient id="rg-ch5-crystal">
    <stop offset="0%" stop-color="rgba(125,249,255,0.6)"/>
    <stop offset="50%" stop-color="rgba(125,249,255,0.15)"/>
    <stop offset="100%" stop-color="rgba(125,249,255,0)"/>
  </radialGradient>
  <radialGradient id="rg-ch5-shield">
    <stop offset="0%" stop-color="rgba(125,249,255,0.15)"/>
    <stop offset="70%" stop-color="rgba(147,112,219,0.08)"/>
    <stop offset="100%" stop-color="rgba(147,112,219,0)"/>
  </radialGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-ch5)"/>`;

// ── STORM CLOUDS ──
for (let i = 0; i < 8; i++) {
  const ccx = (w*(-0.1)+i*w*0.18+mt*12)%(w+100)-50;
  const ccy = h*0.04+Math.sin(i*1.7)*h*0.04;
  const ccr = 35+Math.sin(i*2.3)*12;
  svg += `<ellipse cx="${ccx}" cy="${ccy}" rx="${ccr}" ry="${ccr*0.4}" fill="#1A2030" opacity="0.7"/>`;
  svg += `<ellipse cx="${ccx-ccr*0.3}" cy="${ccy+3}" rx="${ccr*0.7}" ry="${ccr*0.3}" fill="#1A2030" opacity="0.6"/>`;
  svg += `<ellipse cx="${ccx+ccr*0.4}" cy="${ccy+2}" rx="${ccr*0.6}" ry="${ccr*0.25}" fill="#1A2030" opacity="0.55"/>`;
}

// ── Lightning flashes (intermittent) ──
const lightning = Math.sin(mt*3.7)>0.95;
if (lightning) {
  svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="rgba(200,220,255,0.08)"/>`;
  const lx = w*(0.3+Math.sin(mt*7)*0.3);
  svg += `<path d="M${lx} ${h*0.05} L${lx-8} ${h*0.15} L${lx+5} ${h*0.15} L${lx-3} ${h*0.28}" fill="none" stroke="rgba(200,220,255,0.6)" stroke-width="2"/>`;
}

// ── Distant mountains (barely visible in storm) ──
svg += `<path d="M0 ${h*0.35} Q${w*0.15} ${h*0.25} ${w*0.3} ${h*0.3} Q${w*0.5} ${h*0.2} ${w*0.7} ${h*0.28} Q${w*0.85} ${h*0.22} ${w} ${h*0.3} L${w} ${h} L0 ${h} Z" fill="#3A4A5A" opacity="0.3"/>`;

// ── FROZEN LAKE (main stage) ──
const lakeY = h*0.5;
svg += `<rect x="0" y="${lakeY}" width="${w}" height="${h-lakeY}" fill="${isN?'#1A2A40':'#6090B0'}" opacity="0.85"/>`;
// Ice surface
svg += `<rect x="0" y="${lakeY}" width="${w}" height="${h*0.08}" fill="rgba(180,210,230,0.2)"/>`;
// Cracks in ice
for (let i = 0; i < 8; i++) {
  const crx = w*(0.05+i*0.12);
  const cry = lakeY+h*0.02+Math.sin(i*2.1)*h*0.01;
  const crLen = 15+Math.sin(i*1.7)*10;
  const crAng = Math.sin(i*3.1)*30;
  svg += `<line x1="${crx}" y1="${cry}" x2="${crx+crLen}" y2="${cry+Math.sin(crAng)*5}" stroke="rgba(200,230,255,0.2)" stroke-width="0.8"/>`;
  svg += `<line x1="${crx+crLen*0.4}" y1="${cry}" x2="${crx+crLen*0.6}" y2="${cry+8}" stroke="rgba(200,230,255,0.15)" stroke-width="0.5"/>`;
}
// Ice shimmer
for (let i = 0; i < 12; i++) {
  const shx = w*(i/12)+Math.sin(mt*0.5+i)*8;
  const shy = lakeY+5+Math.sin(i*1.3)*3;
  svg += `<ellipse cx="${shx}" cy="${shy}" rx="8" ry="2" fill="rgba(200,230,255,${0.06+Math.sin(mt*1.5+i*0.9)*0.04})"/>`;
}

// ── CRYSTAL SHARD (glowing beneath the ice, center) ──
const crysX = w*0.5;
const crysY = lakeY+h*0.15;
const crysPulse = Math.sin(mt*1.2)*0.5+0.5;
svg += `<circle cx="${crysX}" cy="${crysY}" r="${25+crysPulse*10}" fill="url(#rg-ch5-crystal)"/>`;
svg += `<polygon points="${crysX},${crysY-12} ${crysX-8},${crysY+4} ${crysX+8},${crysY+4}" fill="${sc.acc}" opacity="${0.3+crysPulse*0.3}"/>`;
svg += `<polygon points="${crysX},${crysY-12} ${crysX-4},${crysY+4} ${crysX+4},${crysY+4}" fill="#FFF" opacity="${0.15+crysPulse*0.15}"/>`;
// Rippling light from crystal
for (let i = 0; i < 3; i++) {
  const rr = 15+i*12+Math.sin(mt*1.5+i)*5;
  svg += `<circle cx="${crysX}" cy="${crysY}" r="${rr}" fill="none" stroke="${sc.acc}" stroke-width="1" opacity="${0.1-i*0.025+crysPulse*0.05}"/>`;
}

// ═══ CHARACTERS — forming a chain across the ice ═══

// ── Deer (anchoring on shore, left) ──
const ddx3 = w*0.08, ddy3 = lakeY-3;
svg += `<ellipse cx="${ddx3}" cy="${ddy3-8}" rx="13" ry="9" fill="#C4862D" stroke="#A06820" stroke-width="${ol*0.4}"/>`;
svg += `<path d="M${ddx3+8} ${ddy3-12} Q${ddx3+12} ${ddy3-22} ${ddx3+10} ${ddy3-28}" fill="none" stroke="#C4862D" stroke-width="5.5" stroke-linecap="round"/>`;
svg += `<circle cx="${ddx3+10}" cy="${ddy3-31}" r="4.5" fill="#D4964A"/>`;
svg += `<circle cx="${ddx3+12}" cy="${ddy3-32}" r="0.9" fill="#222"/>`;
for (let i = 0; i < 4; i++) svg += `<line x1="${ddx3-6+i*5}" y1="${ddy3}" x2="${ddx3-6+i*5}" y2="${ddy3+8}" stroke="#A06820" stroke-width="2" stroke-linecap="round"/>`;
// Fawn behind, worried
svg += `<ellipse cx="${ddx3-12}" cy="${ddy3}" rx="7" ry="5" fill="#D4A050"/>`;
svg += `<circle cx="${ddx3-8}" cy="${ddy3-8}" r="3.5" fill="#D4A050"/>`;
svg += `<circle cx="${ddx3-6}" cy="${ddy3-9}" r="1" fill="#222"/>`;

// ── Pup chain (crossing ice) ──
const chainPups = [
  {x:w*0.2, col:'#5AAA5A', scol:'#3A8A3A'},
  {x:w*0.32, col:'#9370DB', scol:'#7B5EA7'},
  {x:w*0.44, col:'#FF8C42', scol:'#D06B20'}
];
for (let p = 0; p < 3; p++) {
  const ppx = chainPups[p].x;
  const ppy = lakeY+3+Math.sin(mt*1.2+p*0.8)*2;
  const slip = Math.sin(mt*2+p*1.5)*2;
  svg += `<ellipse cx="${ppx}" cy="${ppy-3+slip}" rx="6" ry="4.5" fill="${chainPups[p].col}" stroke="${chainPups[p].scol}" stroke-width="${ol*0.4}"/>`;
  svg += `<circle cx="${ppx+4}" cy="${ppy-8+slip}" r="4.5" fill="${chainPups[p].col}" stroke="${chainPups[p].scol}" stroke-width="${ol*0.4}"/>`;
  // Determined eyes
  svg += `<circle cx="${ppx+3}" cy="${ppy-9+slip}" r="1" fill="#222"/>`;
  svg += `<circle cx="${ppx+6}" cy="${ppy-9+slip}" r="1" fill="#222"/>`;
  // Legs splayed on ice
  svg += `<line x1="${ppx-4}" y1="${ppy+slip}" x2="${ppx-7}" y2="${ppy+5}" stroke="${chainPups[p].scol}" stroke-width="2" stroke-linecap="round"/>`;
  svg += `<line x1="${ppx+4}" y1="${ppy+slip}" x2="${ppx+7}" y2="${ppy+5}" stroke="${chainPups[p].scol}" stroke-width="2" stroke-linecap="round"/>`;
  // Connecting line (holding paws/tails)
  if (p < 2) {
    svg += `<line x1="${ppx+7}" y1="${ppy-3+slip}" x2="${chainPups[p+1].x-5}" y2="${lakeY+Math.sin(mt*1.2+(p+1)*0.8)*2}" stroke="rgba(255,255,255,0.3)" stroke-width="1.5" stroke-dasharray="3,2"/>`;
  }
}
// Line from deer to first pup
svg += `<line x1="${ddx3+10}" y1="${ddy3}" x2="${chainPups[0].x-5}" y2="${lakeY+5}" stroke="rgba(255,255,255,0.25)" stroke-width="1.5" stroke-dasharray="3,2"/>`;

// ── PRINCESS (ahead, projecting magic shield) ──
const prx2 = w*0.58, pry2 = lakeY-2;
svg += `<polygon points="${prx2},${pry2-25} ${prx2-12},${pry2+2} ${prx2+12},${pry2+2}" fill="#6A5ACD" stroke="#483D8B" stroke-width="${ol*0.5}" opacity="0.85"/>`;
svg += `<circle cx="${prx2}" cy="${pry2-30}" r="5.5" fill="#FFDAB9" stroke="#DEB887" stroke-width="${ol*0.3}"/>`;
svg += `<path d="M${prx2+3} ${pry2-28} Q${prx2+9+Math.sin(mt*0.9)*3} ${pry2-20} ${prx2+7}" y2="${pry2-12}" fill="none" stroke="#F5DEB3" stroke-width="2.5" stroke-linecap="round"/>`;
svg += `<path d="M${prx2-4} ${pry2-38} L${prx2-2} ${pry2-42} L${prx2} ${pry2-39} L${prx2+2} ${pry2-42} L${prx2+4} ${pry2-38}" fill="none" stroke="${sc.acc}" stroke-width="1.5"/>`;
// Arms raised — projecting shield
svg += `<line x1="${prx2-10}" y1="${pry2-18}" x2="${prx2-20}" y2="${pry2-28}" stroke="#FFDAB9" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${prx2+10}" y1="${pry2-18}" x2="${prx2+20}" y2="${pry2-28}" stroke="#FFDAB9" stroke-width="2" stroke-linecap="round"/>`;
// MAGIC SHIELD DOME
const shieldR = 80+w2*15;
const shieldOp = 0.08+Math.sin(mt*1.5)*0.04;
svg += `<ellipse cx="${w*0.38}" cy="${lakeY}" rx="${shieldR}" ry="${shieldR*0.6}" fill="url(#rg-ch5-shield)"/>`;
// Shield edge sparkles
for (let i = 0; i < 12; i++) {
  const sa = i*(Math.PI*2/12)+mt*0.5;
  const srx = w*0.38+Math.cos(sa)*shieldR;
  const sry = lakeY+Math.sin(sa)*shieldR*0.6;
  if (sry < lakeY+5) {
    svg += `<circle cx="${srx}" cy="${sry}" r="${1+Math.sin(mt*2+i)*0.5}" fill="${sc.acc}" opacity="${0.2+Math.sin(mt*2.5+i*0.7)*0.2}"/>`;
  }
}

// ── Owl flying in storm (above, scouting) ──
const ofx = w*0.45+Math.sin(mt*0.6)*w*0.15;
const ofy = h*0.2+Math.cos(mt*0.4)*15;
const owW = Math.sin(mt*3.5)*10;
svg += `<ellipse cx="${ofx}" cy="${ofy}" rx="5.5" ry="4.5" fill="#8B6B4A"/>`;
svg += `<circle cx="${ofx}" cy="${ofy-4.5}" r="3.5" fill="#9B7B5A"/>`;
svg += `<path d="M${ofx-5.5} ${ofy} Q${ofx-14} ${ofy-owW} ${ofx-18} ${ofy+1}" fill="none" stroke="#8B6B4A" stroke-width="2.5" stroke-linecap="round"/>`;
svg += `<path d="M${ofx+5.5} ${ofy} Q${ofx+14} ${ofy-owW} ${ofx+18} ${ofy+1}" fill="none" stroke="#8B6B4A" stroke-width="2.5" stroke-linecap="round"/>`;
svg += `<circle cx="${ofx-1.5}" cy="${ofy-5}" r="1.8" fill="#FFD700"/>`;
svg += `<circle cx="${ofx+1.5}" cy="${ofy-5}" r="1.8" fill="#FFD700"/>`;
svg += `<circle cx="${ofx-1.5}" cy="${ofy-5}" r="0.7" fill="#222"/>`;
svg += `<circle cx="${ofx+1.5}" cy="${ofy-5}" r="0.7" fill="#222"/>`;

// ── Snowman on far shore (cheering) ──
const smx2 = w*0.85, smy2 = lakeY-2;
svg += `<circle cx="${smx2}" cy="${smy2}" r="10" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${smx2}" cy="${smy2-16}" r="7" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${smx2}" cy="${smy2-28}" r="5.5" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${smx2-2}" cy="${smy2-30}" r="1" fill="#222"/>`;
svg += `<circle cx="${smx2+2}" cy="${smy2-30}" r="1" fill="#222"/>`;
svg += `<polygon points="${smx2},${smy2-28} ${smx2+5},${smy2-27} ${smx2},${smy2-26}" fill="#FF8C42"/>`;
const smWave = Math.sin(mt*4)*12;
svg += `<line x1="${smx2+7}" y1="${smy2-18}" x2="${smx2+18}" y2="${smy2-26+smWave}" stroke="#6B4F2A" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${smx2-7}" y1="${smy2-18}" x2="${smx2-18}" y2="${smy2-26-smWave}" stroke="#6B4F2A" stroke-width="2" stroke-linecap="round"/>`;

// ── Golden butterfly circling crystal ──
const bfa5 = mt*1.2;
const bfx5 = crysX+Math.cos(bfa5)*20;
const bfy5 = crysY-10+Math.sin(bfa5)*8;
const bfW5 = Math.sin(mt*7)*4;
svg += `<ellipse cx="${bfx5-2}" cy="${bfy5}" rx="${3+bfW5*0.3}" ry="4" fill="#FFD700" opacity="0.8" transform="rotate(${-bfW5*2} ${bfx5-2} ${bfy5})"/>`;
svg += `<ellipse cx="${bfx5+2}" cy="${bfy5}" rx="${3+bfW5*0.3}" ry="4" fill="#FFD700" opacity="0.8" transform="rotate(${bfW5*2} ${bfx5+2} ${bfy5})"/>`;
svg += `<ellipse cx="${bfx5}" cy="${bfy5}" rx="0.7" ry="2.5" fill="#8B6914"/>`;
svg += `<circle cx="${bfx5}" cy="${bfy5}" r="${6+w3*3}" fill="#FFD700" opacity="${0.04+w1*0.03}"/>`;

// ── SNOW & WIND (heavy) ──
for (let i = 0; i < 35; i++) {
  const sfx = (Math.sin(i*73.1+5.3)*0.5+0.5)*w+Math.sin(mt*0.8+i*0.4)*20+(mt*15+i*10)%40;
  const sfy = ((mt*12+i*(h/35))%(h+20))-10;
  const sfr = 1.2+Math.sin(i*2.3)*0.7;
  svg += `<circle cx="${sfx%w}" cy="${sfy}" r="${sfr}" fill="#FFF" opacity="${0.3+Math.sin(mt*1.5+i*0.7)*0.2}"/>`;
}
// Wind streaks
for (let i = 0; i < 6; i++) {
  const wsx = (mt*40+i*w*0.18)%w;
  const wsy = h*0.15+i*h*0.1+Math.sin(i*2.3)*h*0.03;
  svg += `<line x1="${wsx}" y1="${wsy}" x2="${wsx+30+Math.sin(i)*10}" y2="${wsy+2}" stroke="rgba(200,220,240,0.12)" stroke-width="1" stroke-linecap="round"/>`;
}
